/** Browser controller for one session's Timeline projection and branch mutations. */
import type {
  ClientContext,
  ConversationSnapshot,
  ISessions,
  ObservableSnapshot,
  SessionFace,
  SessionId,
  SessionListState,
  SnapshotStore,
} from '@deepseek-ai/dsh-client-runtime/client'
import { createSnapshotStore } from '@deepseek-ai/dsh-client-runtime/client'
import {
  MESSAGE_EDIT_PATH,
  type CascadePolicy,
  type DeletePreviewFile,
  type DeleteSkippedFile,
  type EditableBlockKind,
  type EditableMessageBlock,
  type EditOperation,
  type MessageEditDeletePreview,
  type MessageEditOperation,
  type MessageEditOperationResult,
  type MessageEditTimeline,
  type RetryOperation,
  type RetryableTurn,
  type VersionOperation,
  type VersionSummary,
} from '../shared.ts'

/** Reactive controller state shared by the Timeline and header entries. */
export interface MessageEditState {
  status: 'idle' | 'loading' | 'ready' | 'error'
  error: string | null
  pending: VersionOperation | null
  timeline: MessageEditTimeline | null
  switchingTo: string | null
  /** The session's agent is streaming a response; mutations are rejected. */
  busy: boolean
  /** An in-place edit is queued and the regenerated turn has not landed yet. */
  regenerating: boolean
  /** Optimistic edited-message preview for an in-flight in-place edit. */
  optimisticEdit: { turn: number; eventSeq: number; text: string } | null
  /** Open delete-confirmation dialog state (chat turn-tail entry point). */
  deleteDialog: {
    eventSeq: number
    preview: MessageEditDeletePreview | null
    error: string | null
    rollback: boolean
  } | null
}

/** Merge a burst of turn completions into one refresh. */
const REFRESH_DELAY_MS = 300

/** Minimal local stub for a new child branch before the next server round-trip. */
interface StubVersion {
 sessionId: string
 parentSessionId: string
 createdAt: number
 depth: number
 current: boolean
 onCurrentEffectPath: boolean
 operation?: VersionOperation
 cascade?: CascadePolicy | undefined
 targetTurn?: number
 blockKind?: EditableBlockKind
 before?: string
 after?: string
}

/** Plain business face; the renderer binds the reserved source compartment. */
export interface MessageEditFace {
  hooks: { messageEdit: ObservableSnapshot<MessageEditState> }
  acquire(): () => void
  load(): void
  edit(message: EditableMessageBlock, text: string, cascade: CascadePolicy): Promise<boolean>
  retry(turn: number, cascade: CascadePolicy): Promise<boolean>
  reroll(): Promise<boolean>
  /** Fetch the read-only impact report backing the delete confirmation. */
  previewDelete(eventSeq: number): Promise<MessageEditDeletePreview>
  /** Delete a settled user exchange; optionally roll back its workspace files. */
  deleteMessage(eventSeq: number, rollbackWorkspace: boolean): Promise<boolean>
  /** Open the delete confirmation dialog for one settled user message. */
  openDelete(eventSeq: number): void
  /** Close the delete confirmation dialog without deleting. */
  closeDelete(): void
  /** Toggle the workspace-rollback checkbox inside the open dialog. */
  setDeleteRollback(next: boolean): void
  openVersion(sessionId: string): Promise<void>
  exportBranch(format?: 'json' | 'markdown'): void
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function objectValue(value: unknown, label: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new TypeError(`${label} is not an object`)
  }
  return value as Record<string, unknown>
}

function stringValue(value: unknown, label: string): string {
  if (typeof value !== 'string') throw new TypeError(`${label} is not a string`)
  return value
}

function numberValue(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new TypeError(`${label} is not a number`)
  return value
}

function booleanValue(value: unknown, label: string): boolean {
  if (typeof value !== 'boolean') throw new TypeError(`${label} is not a boolean`)
  return value
}

function blockKind(value: unknown): EditableBlockKind {
  if (value !== 'user' && value !== 'assistant.reasoning' && value !== 'assistant.response') {
    throw new TypeError('Invalid message block kind')
  }
  return value
}

function decodeMessage(value: unknown, index: number): EditableMessageBlock {
  const row = objectValue(value, `messages[${String(index)}]`)
  return {
    key: stringValue(row['key'], 'message key'),
    turn: numberValue(row['turn'], 'message turn'),
    eventSeq: numberValue(row['eventSeq'], 'message eventSeq'),
    blockIndex: numberValue(row['blockIndex'], 'message blockIndex'),
    kind: blockKind(row['kind']),
    text: stringValue(row['text'], 'message text'),
    time: numberValue(row['time'], 'message time'),
  }
}

function decodeRetryable(value: unknown, index: number): RetryableTurn {
  const row = objectValue(value, `retryableTurns[${String(index)}]`)
  return {
    turn: numberValue(row['turn'], 'turn'),
    userEventSeq: numberValue(row['userEventSeq'], 'turn userEventSeq'),
    preview: stringValue(row['preview'], 'turn preview'),
    time: numberValue(row['time'], 'turn time'),
  }
}

function optionalOperation(value: unknown): VersionOperation | undefined {
  if (value === undefined) return undefined
  if (value === 'edit' || value === 'reroll' || value === 'retry') return value
  throw new TypeError('Invalid version operation')
}

function decodeVersion(value: unknown, index: number): VersionSummary {
  const row = objectValue(value, `versions[${String(index)}]`)
  const operation = optionalOperation(row['operation'])
  const cascade = row['cascade']
  if (cascade !== undefined && cascade !== 'truncate' && cascade !== 'preserve') {
    throw new TypeError('Invalid version cascade')
  }
  const kind = row['blockKind'] === undefined ? undefined : blockKind(row['blockKind'])
  return {
    sessionId: stringValue(row['sessionId'], 'version sessionId'),
    ...row['parentSessionId'] === undefined
      ? {}
      : { parentSessionId: stringValue(row['parentSessionId'], 'version parentSessionId') },
    ...row['effectId'] === undefined
      ? {}
      : { effectId: stringValue(row['effectId'], 'version effectId') },
    ...row['inverseSessionId'] === undefined
      ? {}
      : { inverseSessionId: stringValue(row['inverseSessionId'], 'version inverseSessionId') },
    createdAt: numberValue(row['createdAt'], 'version createdAt'),
    depth: numberValue(row['depth'], 'version depth'),
    current: booleanValue(row['current'], 'version current'),
    onCurrentEffectPath: booleanValue(row['onCurrentEffectPath'], 'version onCurrentEffectPath'),
    ...operation === undefined ? {} : { operation },
    ...cascade === undefined ? {} : { cascade },
    ...row['targetTurn'] === undefined ? {} : { targetTurn: numberValue(row['targetTurn'], 'version targetTurn') },
    ...kind === undefined ? {} : { blockKind: kind },
    ...row['before'] === undefined ? {} : { before: stringValue(row['before'], 'version before') },
    ...row['after'] === undefined ? {} : { after: stringValue(row['after'], 'version after') },
  }
}

function arrayValue(value: unknown, label: string): unknown[] {
  if (!Array.isArray(value)) throw new TypeError(`${label} is not an array`)
  return value
}

function stringArray(value: unknown, label: string): string[] {
  return arrayValue(value, label).map((item, index) => stringValue(item, `${label}[${String(index)}]`))
}

function decodeTimeline(value: unknown): MessageEditTimeline {
  const data = objectValue(value, 'Timeline response')
  return {
    sessionId: stringValue(data['sessionId'], 'Timeline sessionId'),
    messages: arrayValue(data['messages'], 'Timeline messages').map(decodeMessage),
    retryableTurns: arrayValue(data['retryableTurns'], 'Timeline retryableTurns').map(decodeRetryable),
    versions: arrayValue(data['versions'], 'Timeline versions').map(decodeVersion),
    undoStack: stringArray(data['undoStack'], 'Timeline undoStack'),
    redoSessionIds: stringArray(data['redoSessionIds'], 'Timeline redoSessionIds'),
  }
}

function decodeOperationResult(value: unknown): MessageEditOperationResult {
  const data = objectValue(value, 'Operation response')
  const result: MessageEditOperationResult = {
    sessionId: stringValue(data['sessionId'], 'operation sessionId'),
    queuedTurns: numberValue(data['queuedTurns'], 'operation queuedTurns'),
  }
  if (data['alreadyDeleted'] === true) result.alreadyDeleted = true
  if (typeof data['delete'] === 'object' && data['delete'] !== null) {
    const detail = objectValue(data['delete'], 'delete result')
    const turns = Array.isArray(detail['removedTurns'])
      ? detail['removedTurns'].map((turn): number => numberValue(turn, 'removedTurns entry'))
      : []
    result.delete = {
      removedTurns: turns,
      revertedFiles: numberValue(detail['revertedFiles'], 'delete revertedFiles'),
      removedFiles: numberValue(detail['removedFiles'], 'delete removedFiles'),
      skippedFiles: numberValue(detail['skippedFiles'], 'delete skippedFiles'),
      workspaceRolledBack: booleanValue(detail['workspaceRolledBack'], 'delete workspaceRolledBack'),
      auditId: stringValue(detail['auditId'], 'delete auditId'),
    }
  }
  return result
}

/** Decode one file row of the delete preview payload. */
function decodeDeleteFile(value: unknown, index: number, change: 'revert' | 'remove'): DeletePreviewFile {
  const row = objectValue(value, `files[${String(index)}]`)
  return { path: stringValue(row['path'], 'file path'), change }
}

/** Decode the host's read-only delete impact report. */
function decodeDeletePreview(value: unknown): MessageEditDeletePreview {
  const data = objectValue(value, 'Delete preview response')
  const laterTurns = Array.isArray(data['laterTurns'])
    ? data['laterTurns'].map((turn): number => numberValue(turn, 'laterTurns entry'))
    : []
  const filesToRevert = Array.isArray(data['filesToRevert'])
    ? data['filesToRevert'].map((row, index) => decodeDeleteFile(row, index, 'revert'))
    : []
  const filesToRemove = Array.isArray(data['filesToRemove'])
    ? data['filesToRemove'].map((row, index) => decodeDeleteFile(row, index, 'remove'))
    : []
  const skipped: DeleteSkippedFile[] = Array.isArray(data['skipped'])
    ? data['skipped'].map((raw, index): DeleteSkippedFile => {
        const row = objectValue(raw, `skipped[${String(index)}]`)
        return {
          path: stringValue(row['path'], 'skipped path'),
          reason: row['reason'] === 'too-large' ? 'too-large' : 'binary',
        }
      })
    : []
  const warnings = Array.isArray(data['warnings'])
    ? data['warnings'].map((warning): string => stringValue(warning, 'warning'))
    : []
  const checkpointReason = typeof data['checkpointReason'] === 'string' ? data['checkpointReason'] : undefined
  const workspacePath = typeof data['workspacePath'] === 'string' ? data['workspacePath'] : undefined
  return {
    sessionId: stringValue(data['sessionId'], 'preview sessionId'),
    eventSeq: numberValue(data['eventSeq'], 'preview eventSeq'),
    turn: numberValue(data['turn'], 'preview turn'),
    preview: stringValue(data['preview'], 'preview text'),
    laterTurns,
    willBranch: booleanValue(data['willBranch'], 'preview willBranch'),
    checkpointFound: booleanValue(data['checkpointFound'], 'preview checkpointFound'),
    ...(checkpointReason === undefined ? {} : { checkpointReason }),
    ...(workspacePath === undefined ? {} : { workspacePath }),
    filesToRevert,
    filesToRemove,
    skipped,
    warnings,
  }
}

async function responseValue(response: Response): Promise<unknown> {
  const value = await response.json() as unknown
  if (response.ok) return value
  const error = objectValue(value, 'Error response')['error']
  throw new Error(typeof error === 'string' ? error : `Request failed: HTTP ${String(response.status)}`)
}

function conversationRevision(snapshot: ConversationSnapshot): string {
  const turnEnds = [...snapshot.turnEnds.entries()]
    .map(([turn, seq]) => `${String(turn)}:${String(seq)}`)
    .join(',')
  return [snapshot.openState, snapshot.removed, snapshot.hasMore, turnEnds].join('|')
}

function lineageRevision(snapshot: SessionListState, sessionId: SessionId): string {
  let root = sessionId
  const ancestorIds = new Set<SessionId>()
  while (!ancestorIds.has(root)) {
    ancestorIds.add(root)
    const parent = snapshot.byId[root]?.parentId
    if (parent === undefined || snapshot.byId[parent] === undefined) break
    root = parent
  }

  const connected: string[] = []
  for (const rawId of Object.keys(snapshot.byId).sort()) {
    const id = rawId as SessionId
    const seen = new Set<SessionId>()
    let cursor: SessionId | undefined = id
    while (cursor !== undefined && !seen.has(cursor)) {
      if (cursor === root) {
        connected.push(`${id}>${snapshot.byId[id]?.parentId ?? ''}`)
        break
      }
      seen.add(cursor)
      cursor = snapshot.byId[cursor]?.parentId
    }
  }
  return connected.join('|')
}

/** One stable controller is shared by all entries mounted for the same session. */
export class MessageEditController {
  readonly store: SnapshotStore<MessageEditState> = createSnapshotStore<MessageEditState>({
    status: 'idle',
    error: null,
    pending: null,
    timeline: null,
    switchingTo: null,
    busy: false,
    regenerating: false,
    optimisticEdit: null,
    deleteDialog: null,
  })

  readonly face: MessageEditFace
  private generation = 0
  private readonly ctx: ClientContext
  private readonly sessions: ISessions
  private sessionSource: SessionFace | undefined
  private sessionSourceDispose: (() => void) | undefined
  private sessionRevision: string | undefined
  private listRevision = ''
  private refreshScheduled = false
  private refreshTimer: ReturnType<typeof setTimeout> | undefined
  private observing = false
  private readonly navigationWaits = new Set<() => void>()
  private disposeObservation: (() => Promise<void>) | undefined = undefined
  private inflight: Promise<void> | null = null
  private rerunAfter = false
  private abort: AbortController | null = null
  private disposed = false
  private users = 0

  constructor(
    ctx: ClientContext,
    private readonly sessionId: SessionId,
  ) {
    this.ctx = ctx
    this.sessions = ctx.get('sessions') as unknown as ISessions
    this.face = {
      hooks: { messageEdit: this.store },
      acquire: () => {
        this.users += 1
        if (this.users === 1 && this.disposed) this.revive()
        return () => this.release()
      },
      load: () => { void this.load() },
      edit: (message, text, cascade) => this.mutate({
        action: 'edit',
        sessionId: this.sessionId,
        eventSeq: message.eventSeq,
        blockIndex: message.blockIndex,
        text,
        cascade,
      }),
      retry: (turn, cascade) => this.mutate({
        action: 'retry',
        sessionId: this.sessionId,
        turn,
        cascade,
      }),
      reroll: () => this.mutate({ action: 'reroll', sessionId: this.sessionId }),
      previewDelete: eventSeq => this.fetchPreviewReport(eventSeq),
      deleteMessage: (eventSeq, rollbackWorkspace) => this.mutate({
        action: 'delete',
        sessionId: this.sessionId,
        eventSeq,
        rollbackWorkspace,
      }),
      openDelete: (eventSeq) => {
        this.store.update((state) => {
          state.deleteDialog = { eventSeq, preview: null, error: null, rollback: true }
        })
        this.fetchPreviewReport(eventSeq)
          .then((preview) => {
            this.store.update((state) => {
              if (state.deleteDialog === null || state.deleteDialog.eventSeq !== eventSeq) return
              state.deleteDialog.preview = preview
              state.deleteDialog.rollback = preview.checkpointFound
            })
          })
          .catch((error) => {
            this.store.update((state) => {
              if (state.deleteDialog === null || state.deleteDialog.eventSeq !== eventSeq) return
              state.deleteDialog.error = messageOf(error)
            })
          })
      },
      closeDelete: () => {
        this.store.update((state) => { state.deleteDialog = null })
      },
      setDeleteRollback: (next) => {
        this.store.update((state) => {
          if (state.deleteDialog !== null) state.deleteDialog.rollback = next
        })
      },
      openVersion: sessionId => this.openWhenListed(sessionId as SessionId),
      exportBranch: (format) => this.downloadTimeline(format),
    }
    this.observe()
  }

  private parentVersionSnapshot(): { sessionId: string; depth: number } | null {
    const timeline = this.store.getSnapshot().timeline
    if (timeline === null) return null
    const current = timeline.versions.find(version => version.current) ?? timeline.versions.at(-1) ?? null
    return current === null ? null : { sessionId: current.sessionId, depth: current.depth }
  }

  private appendStubVersion(childSessionId: string, operation: MessageEditOperation): void {
    const timeline = this.store.getSnapshot().timeline
    if (timeline === null) return
    const parent = this.parentVersionSnapshot()
    const parentId = parent?.sessionId ?? timeline.sessionId
    const depth = (parent?.depth ?? 0) + 1
    const eventSeq = operation.action === 'edit' ? (operation as EditOperation).eventSeq : undefined
    const messageForEventSeq = eventSeq !== undefined ? timeline.messages.find((candidate) => candidate.eventSeq === eventSeq) : undefined
    const eventTurn = messageForEventSeq?.turn ?? 0
    const stub: StubVersion = {
      sessionId: childSessionId,
      parentSessionId: parentId,
      createdAt: Date.now(),
      depth,
      current: true,
      onCurrentEffectPath: true,
      operation: operation.action,
      cascade: operation.action === 'edit' || operation.action === 'retry'
        ? (operation as EditOperation | RetryOperation).cascade
        : undefined,
      ...operation.action === 'edit'
        ? {
            targetTurn: eventTurn,
            targetEventSeq: operation.eventSeq,
            targetBlockIndex: operation.blockIndex,
            blockKind: 'user',
          }
        : operation.action === 'retry'
          ? { targetTurn: operation.turn }
          : {},
    }
    const stamped: VersionSummary = {
      ...stub,
      current: true,
      onCurrentEffectPath: true,
    } as unknown as VersionSummary
    this.store.update((state) => {
      if (state.timeline === null) return
      state.timeline = {
        ...state.timeline,
        versions: [
          ...state.timeline.versions.map(version => ({
            ...version,
            current: false,
            onCurrentEffectPath: false,
          })),
          stamped,
        ],
        undoStack: [childSessionId, ...state.timeline.undoStack],
        redoSessionIds: [],
      }
    })
  }

  private downloadTimeline(format?: 'json' | 'markdown'): void {
    const snapshot = this.store.getSnapshot()
    if (snapshot.timeline === null) return
    const timeline = snapshot.timeline
    const payload = {
      sessionId: timeline.sessionId,
      exportedAt: new Date().toISOString(),
      versions: timeline.versions,
      messages: timeline.messages,
      retryableTurns: timeline.retryableTurns,
      undoStack: timeline.undoStack,
      redoSessionIds: timeline.redoSessionIds,
    }
    if (format === 'markdown') {
      const lines: string[] = []
      lines.push(`# Timeline Export`)
      lines.push('')
      lines.push(`Session: ${payload.sessionId}`)
      lines.push(`Exported: ${payload.exportedAt}`)
      lines.push('')
      lines.push('---')
      lines.push('')
      lines.push('## Versions')
      lines.push('')
      for (const version of payload.versions) {
        const marker = version.current ? ' [CURRENT]' : version.onCurrentEffectPath ? ' [ON PATH]' : ''
        const label = version.operation ? `${version.operation} turn ${version.targetTurn ?? '?'}${marker}` : 'Original'
        lines.push(`- ${label} \`${version.sessionId.slice(0, 12)}\``)
      }
      lines.push('')
      lines.push('---')
      lines.push('')
      lines.push('## Messages')
      lines.push('')
      for (const turn of payload.retryableTurns) {
        lines.push(`### Turn ${turn.turn}`)
        lines.push('')
        const messages = payload.messages.filter(message => message.turn === turn.turn)
        for (const message of messages) {
          const kind = message.kind === 'user' ? 'User' : message.kind === 'assistant.reasoning' ? 'Assistant Reasoning' : 'Assistant Response'
          lines.push(`**${kind}** \`${message.time ? new Date(message.time).toISOString() : ''}\``)
          lines.push('')
          lines.push(message.text || '(empty)')
          lines.push('')
        }
      }
      lines.push('---')
      lines.push('')
      lines.push('## JSON')
      lines.push('')
      lines.push('```json')
      lines.push(JSON.stringify(payload, null, 2))
      lines.push('```')
      lines.push('')
      const markdown = lines.join('\n')
      this.scheduleDownload(`timeline-${timeline.sessionId.slice(0, 8)}.md`, markdown, 'text/markdown')
      return
    }
    const json = JSON.stringify(payload, null, 2)
    this.scheduleDownload(`timeline-${timeline.sessionId.slice(0, 8)}.json`, json, 'application/json')
  }

  private scheduleDownload(filename: string, content: string, mimeType: string): void {
    const blob = new Blob([content], { type: mimeType })
    const url = URL.createObjectURL(blob)
    if (typeof document === 'undefined') {
      URL.revokeObjectURL(url)
      return
    }
    try {
      const a = document.createElement('a')
      a.href = url
      a.download = filename
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
    } finally {
      URL.revokeObjectURL(url)
    }
  }

  private observe(): void {
    this.disposeObservation = this.ctx.effect(
      () => this.observeDependencies(),
      `message-edit-enhanced: observe ${this.sessionId}`,
    )
  }

  private release(): void {
    this.users -= 1
    if (this.users <= 0) this.dispose()
  }

  /** Tear subscriptions down once no mounted entry uses this controller. */
  private dispose(): void {
    if (this.disposed) return
    this.disposed = true
    this.generation += 1
    if (this.refreshTimer !== undefined) {
      clearTimeout(this.refreshTimer)
      this.refreshTimer = undefined
      this.refreshScheduled = false
    }
    this.abort?.abort()
    this.abort = null
    void this.disposeObservation?.()
    this.disposeObservation = undefined
  }

  /** Re-observe after a transient zero; the retained store keeps old data
   * until the immediate refetch below commits. */
  private revive(): void {
    this.disposed = false
    this.observe()
    this.refresh()
  }

  /** Bind to replaceable value sources instead of retaining a Session object. */
  private observeDependencies(): () => void {
    this.observing = true
    this.listRevision = lineageRevision(this.sessions.list.getSnapshot(), this.sessionId)
    this.bindSessionSource()
    const disposeList = this.sessions.list.subscribe(() => {
      const rebound = this.bindSessionSource()
      const nextRevision = lineageRevision(this.sessions.list.getSnapshot(), this.sessionId)
      if (nextRevision === this.listRevision && !rebound) return
      this.listRevision = nextRevision
      this.invalidate()
    })
    return () => {
      this.observing = false
      this.generation += 1
      disposeList()
      this.sessionSourceDispose?.()
      this.sessionSourceDispose = undefined
      this.sessionSource = undefined
      this.sessionRevision = undefined
      for (const cancel of [...this.navigationWaits]) cancel()
    }
  }

  private bindSessionSource(): boolean {
    const source = this.sessions.binding(this.sessionId)?.session
    if (source === this.sessionSource) return false
    this.sessionSourceDispose?.()
    this.sessionSource = source
    this.sessionRevision = source === undefined ? undefined : conversationRevision(source.getSnapshot())
    if (source !== undefined) {
      this.store.update((state) => { state.busy = source.getSnapshot().running })
    }
    this.sessionSourceDispose = source?.subscribe(() => {
      if (this.sessionSource !== source) return
      const snapshot = source.getSnapshot()
      this.store.update((state) => { state.busy = snapshot.running })
      const revision = conversationRevision(snapshot)
      if (revision === this.sessionRevision) return
      this.sessionRevision = revision
      this.invalidate()
    })
    return true
  }

  private invalidate(): void {
    if (!this.observing || this.store.getSnapshot().status === 'idle' || this.refreshScheduled) return
    this.refreshScheduled = true
    this.refreshTimer = setTimeout(() => {
      this.refreshTimer = undefined
      this.refreshScheduled = false
      if (this.observing && this.store.getSnapshot().status !== 'idle') this.refresh()
    }, REFRESH_DELAY_MS)
  }

  /** Invalidation-driven refetch: one in-flight request absorbs the demand
   * and commits a single rerun once it settles. */
  private refresh(): void {
    if (this.disposed) return
    if (this.inflight !== null) {
      this.rerunAfter = true
      return
    }
    void this.load()
  }

  /** Refetch the full value-level projection; concurrent callers share one
   * request, and an invalidation during flight schedules exactly one rerun. */
  async load(): Promise<void> {
    if (this.disposed) return
    if (this.inflight !== null) return this.inflight
    const generation = ++this.generation
    this.abort?.abort()
    const abort = new AbortController()
    this.abort = abort
    this.store.update((state) => {
      state.status = 'loading'
      state.error = null
    })
    const run = this.performLoad(generation, abort)
    this.inflight = run
    try {
      await run
    } finally {
      if (this.inflight === run) this.inflight = null
      if (this.rerunAfter && !this.disposed) {
        this.rerunAfter = false
        void this.load()
      }
    }
  }

  private async performLoad(generation: number, abort: AbortController): Promise<void> {
    try {
      const response = await fetch(`${MESSAGE_EDIT_PATH}?sessionId=${encodeURIComponent(this.sessionId)}`, {
        method: 'GET',
        headers: { accept: 'application/json' },
        cache: 'no-store',
        signal: abort.signal,
      })
      const timeline = decodeTimeline(await responseValue(response))
      if (generation !== this.generation) return
      this.store.update((state) => {
        state.status = 'ready'
        state.error = null
        state.timeline = timeline
        // The in-place regenerated turn has landed (its edited user message is
        // now a settled turn in the projection), so retire the optimistic stub.
        if (state.optimisticEdit !== null) {
          const landed = timeline.messages.some(message => message.turn === state.optimisticEdit?.turn)
          if (landed) {
            state.optimisticEdit = null
            state.regenerating = false
          }
        }
      })
    } catch (error) {
      if (generation !== this.generation) return
      this.store.update((state) => {
        state.status = 'error'
        state.error = messageOf(error)
      })
    }
  }

  /** Refresh only controllers whose projection has already been requested. */
  refreshIfLoaded(): void {
    if (this.disposed || this.store.getSnapshot().status === 'idle') return
    if (this.store.getSnapshot().switchingTo !== null) return
    this.refresh()
  }

  private async mutate(operation: MessageEditOperation): Promise<boolean> {
    const current = this.store.getSnapshot()
    if (current.pending !== null || current.status !== 'ready') return false
    if (current.busy || current.regenerating) {
      // The agent is streaming (or an in-place regeneration is in flight);
      // runMaintenance would reject the work with an opaque error, so reject
      // up-front with a clear message.
      this.store.update((state) => {
        state.error = 'The assistant is still responding; wait for it to finish before editing.'
      })
      return false
    }
    this.store.update((state) => {
      state.pending = operation.action
      state.error = null
    })
    try {
      const response = await fetch(MESSAGE_EDIT_PATH, {
        method: 'POST',
        headers: {
          accept: 'application/json',
          'content-type': 'application/json',
        },
        body: JSON.stringify(operation),
      })
      const result = decodeOperationResult(await responseValue(response))
      if (this.disposed) return true
      this.store.update((state) => { state.pending = null })
      if (result.sessionId !== this.sessionId) {
        // Fork fallback (non-live session): the deletion branched instead of
        // truncating, so navigate to the child like any other version op.
        try {
          this.store.update((state) => { state.switchingTo = result.sessionId })
          await this.openWhenListed(result.sessionId as SessionId)
        } finally {
          this.store.update((state) => { state.switchingTo = null })
        }
        this.appendStubVersion(result.sessionId, operation)
        return true
      }
      if (operation.action === 'delete') {
        // In-place truncation does not bump turnEnds, so refresh explicitly.
        // alreadyDeleted results converge to the same visible state.
        this.refreshIfLoaded()
        return true
      }
      if (operation.action === 'edit') {
        // In-place edit: the host truncated and re-sent in the CURRENT session.
        // No navigation and no branch stub. Show an optimistic edited-message
        // preview immediately; the session-event subscription refreshes the
        // timeline when the regenerated turn lands (one refresh, no double GET).
        const edit = operation as EditOperation
        const nextTurn = this.nextTurnAfterCurrent()
        this.store.update((state) => {
          state.optimisticEdit = { turn: nextTurn, eventSeq: edit.eventSeq, text: edit.text }
          state.regenerating = true
        })
      }
      return true
    } catch (error) {
      if (this.disposed) return false
      this.store.update((state) => {
        state.pending = null
        state.regenerating = false
        state.optimisticEdit = null
        state.error = messageOf(error)
      })
      return false
    }
  }

    /** Fetch the host's read-only delete impact report. */
  private async fetchPreviewReport(eventSeq: number): Promise<MessageEditDeletePreview> {
    const url = `${MESSAGE_EDIT_PATH}/delete-preview?sessionId=${encodeURIComponent(this.sessionId)}&eventSeq=${String(eventSeq)}`
    const response = await fetch(url, { method: 'GET', headers: { accept: 'application/json' }, cache: 'no-store' })
    return decodeDeletePreview(await responseValue(response))
  }

/** Next turn number the in-place regeneration will open. */
  private nextTurnAfterCurrent(): number {
    const timeline = this.store.getSnapshot().timeline
    if (timeline === null) return 1
    const last = timeline.messages.reduce((max, message) => Math.max(max, message.turn), 0)
    return last + 1
  }

  /** Session-list publication is the reactive dependency for navigation. */
  private openWhenListed(sessionId: SessionId): Promise<void> {
    if (this.sessions.list.getSnapshot().byId[sessionId] !== undefined) {
      this.sessions.open(sessionId)
      return Promise.resolve()
    }
    return new Promise((resolve) => {
      let settled = false
      let dispose = (): void => {}
      const finish = (open: boolean): void => {
        if (settled) return
        settled = true
        dispose()
        this.navigationWaits.delete(cancel)
        if (open) this.sessions.open(sessionId)
        resolve()
      }
      const cancel = (): void => { finish(false) }
      this.navigationWaits.add(cancel)
      dispose = this.sessions.list.subscribe(() => {
        if (this.sessions.list.getSnapshot().byId[sessionId] === undefined) return
        finish(true)
      })
      if (this.sessions.list.getSnapshot().byId[sessionId] !== undefined) finish(true)
    })
  }
}